import { NextResponse, type NextRequest } from "next/server";

// Generated by localize.dev: the language routing, for an app with a proxy of its own. Regenerated
// by each run. /es/about is served by the /about page in Spanish (a URL per language for search
// engines); unprefixed URLs keep the "lang" cookie and Accept-Language.
const languages = ["en", "es", "ar", "zh-CN"];
const fallbackLng = "en";

/** The language a path starts with and the path without it: /es/dashboard → es, /dashboard. */
export function splitLanguage(pathname: string): { lang: string | null; path: string } {
  const [, first, ...rest] = pathname.split("/");
  if (first && first !== fallbackLng && languages.includes(first)) return { lang: first, path: `/${rest.join("/")}` };
  return { lang: null, path: pathname };
}

/** Return it where your proxy lets a request through (instead of NextResponse.next()). */
export function localizeRequest(request: NextRequest) {
  const { lang, path } = splitLanguage(request.nextUrl.pathname);
  const headers = new Headers(request.headers);
  headers.set("x-localize-path", path);
  if (!lang) return NextResponse.next({ request: { headers } });
  headers.set("x-localize-lang", lang);
  const url = request.nextUrl.clone();
  url.pathname = path;
  return NextResponse.rewrite(url, { request: { headers } });
}
